#include <errno.h>
#include <time.h>

#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/posix/time.h>
#include <zephyr/sys/time_units.h>
#include <zephyr/sys/util.h>
#include <zephyr/internal/syscall_handler.h>

/*
 * `k_uptime_get` returns a timestamp based on an always increasing
 * value from the system start.  To support the `CLOCK_REALTIME`
 * clock, this `rt_clock_base` records the time that the system was
 * started.  This can either be set via `clock_settime`, or could be
 * initialized from a real time clock, if such hardware is present.
 */
static struct timespec rt_clock_base;
static K_MUTEX_DEFINE(rt_clock_base_lock);

static inline int64_t timespec_to_nsec(const struct timespec *ts)
{
	return (int64_t)ts->tv_sec * NSEC_PER_SEC + ts->tv_nsec;
}

int clock_getres(clockid_t clock_id, struct timespec *ts)
{
	if (!(clock_id == CLOCK_MONOTONIC || clock_id == CLOCK_REALTIME ||
	      clock_id == CLOCK_PROCESS_CPUTIME_ID || clock_id == CLOCK_THREAD_CPUTIME_ID)) {
		errno = EINVAL;
		return -1;
	}

	if (ts != NULL) {
		*ts = (struct timespec){
			.tv_sec = 0,
			.tv_nsec = NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC,
		};
	}

	return 0;
}

/**
 * @brief Get current time specified by clock_id.
 *
 * See IEEE 1003.1
 */
int z_impl_clock_gettime(clockid_t clock_id, struct timespec *ts)
{
	uint64_t elapsed_nsecs;
	struct timespec base;

	if (ts == NULL) {
		errno = EFAULT;
		return -1;
	}

	switch (clock_id) {
	case CLOCK_MONOTONIC:
		base.tv_sec = 0;
		base.tv_nsec = 0;
		break;

	case CLOCK_REALTIME:
		(void)k_mutex_lock(&rt_clock_base_lock, K_FOREVER);
		base = rt_clock_base;
		(void)k_mutex_unlock(&rt_clock_base_lock);
		break;

	default:
		errno = EINVAL;
		return -1;
	}

	elapsed_nsecs = k_ ticks_to_ns_floor64(k_uptime_ticks());
	ts->tv_sec = (time_t)(elapsed_nsecs / NSEC_PER_SEC);
	ts->tv_nsec = (long)(elapsed_nsecs % NSEC_PER_SEC);

	ts->tv_sec += base.tv_sec;
	ts->tv_nsec += base.tv_nsec;
	if (ts->tv_nsec >= NSEC_PER_SEC) {
		ts->tv_sec++;
		ts->tv_nsec -= NSEC_PER_SEC;
	}

	return 0;
}

#ifdef CONFIG_USERSPACE
int z_vrfy_clock_gettime(clockid_t clock_id, struct timespec *ts)
{
	struct timespec kts;
	int ret;

	K_OOPS(K_SYSCALL_MEMORY_WRITE(ts, sizeof(*ts)));
	ret = z_impl_clock_gettime(clock_id, &kts);
	if (ret == 0) {
		*ts = kts;
	}
	return ret;
}
#include <syscalls/clock_gettime_mrsh.c>
#endif

/**
 * @brief Set the time of the specified clock.
 *
 * See IEEE 1003.1.
 *
 * Note that only the `CLOCK_REALTIME` clock can be set using this
 * call.
 */
int clock_settime(clockid_t clock_id, const struct timespec *tp)
{
	struct timespec base;

	if (clock_id != CLOCK_REALTIME) {
		errno = EINVAL;
		return -1;
	}

	if (tp == NULL) {
		errno = EFAULT;
		return -1;
	}

	if (tp->tv_nsec < 0 || tp->tv_nsec >= NSEC_PER_SEC) {
		errno = EINVAL;
		return -1;
	}

	uint64_t elapsed_nsecs = k_ticks_to_ns_floor64(k_uptime_ticks());
	int64_t delta = (int64_t)NSEC_PER_SEC * tp->tv_sec + tp->tv_nsec - elapsed_nsecs;

	base.tv_sec = delta / NSEC_PER_SEC;
	base.tv_nsec = delta % NSEC_PER_SEC;
	if (base.tv_nsec < 0) {
		base.tv_sec--;
		base.tv_nsec += NSEC_PER_SEC;
	}

	(void)k_mutex_lock(&rt_clock_base_lock, K_FOREVER);
	rt_clock_base = base;
	(void)k_mutex_unlock(&rt_clock_base_lock);

	return 0;
}

/**
 * @brief Suspend execution for nanosecond intervals.
 *
 * See IEEE 1003.1
 */
static int do_nanosleep(clockid_t clock_id, int flags, const struct timespec *rqtp,
			struct timespec *rmtp)
{
	uint64_t ns;
	uint64_t us;
	uint64_t uptime_ns;
	const bool update_rmtp = rmtp != NULL && (flags & TIMER_ABSTIME) == 0;

	if (!(clock_id == CLOCK_MONOTONIC || clock_id == CLOCK_REALTIME)) {
		return EINVAL;
	}

	if (rqtp == NULL) {
		return EFAULT;
	}

	if (rqtp->tv_sec < 0 || rqtp->tv_nsec < 0 || rqtp->tv_nsec >= NSEC_PER_SEC) {
		return EINVAL;
	}

	if ((flags & TIMER_ABSTIME) != 0) {
		int64_t rqtp_ns = timespec_to_nsec(rqtp);

		if (clock_id == CLOCK_REALTIME) {
			(void)k_mutex_lock(&rt_clock_base_lock, K_FOREVER);
			rqtp_ns -= timespec_to_nsec(&rt_clock_base);
			(void)k_mutex_unlock(&rt_clock_base_lock);
		}

		uptime_ns = k_ticks_to_ns_ceil64(k_uptime_ticks());
		if (rqtp_ns <= uptime_ns) {
			ns = 0;
		} else {
			ns = rqtp_ns - uptime_ns;
		}
	} else {
		if (unlikely(rqtp->tv_sec >= ULLONG_MAX / NSEC_PER_SEC)) {
			ns = k_ sleep(K_SECONDS(rqtp->tv_sec - ULLONG_MAX / NSEC_PER_SEC)) *
				NSEC_PER_MSEC;
			if (ns > 0) {
				if (update_rmtp) {
					rmtp->tv_sec = ns / NSEC_PER_SEC +
						ULLONG_MAX / NSEC_PER_SEC;
					rmtp->tv_nsec = rqtp->tv_nsec + ns % NSEC_PER_SEC;
					if (rmtp->tv_nsec >= NSEC_PER_SEC) {
						rmtp->tv_sec++;
						rmtp->tv_nsec -= NSEC_PER_SEC;
					}
				}

				return EINTR;
			}

			ns = ULLONG_MAX - rqtp->tv_nsec;
		} else {
			ns = rqtp->tv_sec * NSEC_PER_SEC;
		}
		ns += rqtp->tv_nsec;
	}

	us = DIV_ROUND_UP(ns, NSEC_PER_USEC);
	do {
		us = k_usleep(us);
	} while (us != 0);

	if (update_rmtp) {
		rmtp->tv_sec = 0;
		rmtp->tv_nsec = 0;
	}

	return 0;
}

int nanosleep(const struct timespec *rqtp, struct timespec *rmtp)
{
	int ret = do_nanosleep(CLOCK_MONOTONIC, 0, rqtp, rmtp);

	if (ret != 0) {
		errno = ret;
		return -1;
	}

	return 0;
}

int clock_nanosleep(clockid_t clock_id, int flags, const struct timespec *rqtp,
		    struct timespec *rmtp)
{
	if ((flags & ~TIMER_ABSTIME) != 0) {
		return EINVAL;
	}

	return do_nanosleep(clock_id, flags, rqtp, rmtp);
}

/**
 * @brief Get current real time.
 *
 * See IEEE 1003.1
 */
int gettimeofday(struct timeval *tv, void *tz)
{
	struct timespec ts;
	int res;

	/* As per POSIX, "if tzp is not a null pointer, the behavior
	 * is unspecified."  "tzp" is the "tz" parameter above. */
	ARG_UNUSED(tz);

	res = clock_gettime(CLOCK_REALTIME, &ts);
	if (res == 0) {
		tv->tv_sec = ts.tv_sec;
		tv->tv_usec = ts.tv_nsec / NSEC_PER_USEC;
	}

	return res;
}
